#!/usr/bin/env python3
"""
Double-click to open. Put your .env (TTS_APP_KEY / TTS_APP_SECRET) next to this file.
Press Start:  1) optionally export fresh LIVE data from TikTok Shop
              2) choose which CSVs to use
              3) a self-contained dashboard HTML is written to ./dashboards and opened

Created next to this file: exports/ (CSVs), dashboards/ (HTML), tts_tokens.json (login token).
No extra packages needed (standard library only).
"""
import base64, csv, hashlib, hmac, json, os, queue, sys, threading, time, traceback, webbrowser, zlib
import urllib.parse, urllib.request, urllib.error
from datetime import date, timedelta, datetime
from pathlib import Path

APP_NAME = "CashCards LIVE Dashboard"
HERE = Path(sys.argv[0] if getattr(sys, "frozen", False) else __file__).resolve().parent
EXPORTS = HERE / "exports"
DASHBOARDS = HERE / "dashboards"
TOKEN_FILE = HERE / "tts_tokens.json"
API = "https://open-api.tiktokglobalshop.com"
AUTH = "https://auth.tiktok-shops.com"
ACCOUNT_TYPES = ["OFFICIAL_ACCOUNTS", "MARKETING_ACCOUNTS"]
SERVICE_ID = "7684190387405899534"          # KPI Dashboard app (override with TTS_SERVICE_ID in .env)
WORKERS = 6                                   # LIVEs fetched in parallel
CALLBACK_PORT = 8765                          # redirect URL: http://localhost:8765/callback
ENV_PATH = None                               # set by load_env(); the TikTok login is stored in this .env


class AppError(Exception):
    pass


class NeedAuthCode(AppError):
    pass


# =============================================================== config ====
ENV_NAMES = [".env", "env.txt", "env", "config.env", "tts.env", ".env.txt", "env.txt.txt", "config.txt"]


def find_env():
    """The settings file next to the app. Mac Finder won't create '.env', so 'env.txt' etc. also work."""
    for n in ENV_NAMES:
        p = HERE / n
        if p.exists():
            return p
    for p in sorted(HERE.glob("*.env")):
        return p
    return None


def env_vals(path):
    vals = {}
    for line in Path(path).read_text(encoding="utf-8-sig").splitlines():
        if "=" in line and not line.strip().startswith("#"):
            k, v = line.split("=", 1)
            vals[k.strip()] = v.strip().strip('"\'')
    return vals


def load_env(path):
    global ENV_PATH
    vals = env_vals(path)
    key, secret = vals.get("TTS_APP_KEY"), vals.get("TTS_APP_SECRET")
    if not key or not secret:
        raise AppError(f"{path} must contain TTS_APP_KEY=... and TTS_APP_SECRET=...")
    ENV_PATH = Path(path)
    return key, secret


def update_env(path, updates, header="# TikTok Shop login (filled in automatically; anyone with this file can pull shop data)"):
    """Set/replace KEY=value lines in the .env, keeping everything else as is."""
    lines = Path(path).read_text(encoding="utf-8-sig").splitlines()
    done = set()
    for i, line in enumerate(lines):
        k = line.split("=", 1)[0].strip() if "=" in line and not line.strip().startswith("#") else None
        if k in updates:
            lines[i] = f"{k}={updates[k]}"; done.add(k)
    missing = [k for k in updates if k not in done]
    if missing:
        if header not in lines:
            lines += ["", header]
        lines += [f"{k}={updates[k]}" for k in missing]
    Path(path).write_text("\n".join(lines) + "\n", encoding="utf-8")


# ================================================================= http ====
def http_get_json(url, params, headers=None, retries=5):
    full = url + "?" + urllib.parse.urlencode(params)
    for attempt in range(retries):
        req = urllib.request.Request(full, headers=headers or {})
        try:
            with urllib.request.urlopen(req, timeout=60) as r:
                return json.loads(r.read().decode("utf-8"))
        except urllib.error.HTTPError as e:
            if e.code == 429 or e.code >= 500:
                time.sleep(2 ** attempt)
                continue
            try:
                return json.loads(e.read().decode("utf-8"))
            except Exception:
                raise AppError(f"HTTP {e.code} from {url}")
        except urllib.error.URLError as e:
            if attempt == retries - 1:
                raise AppError(f"Network error: {e.reason}")
            time.sleep(2 ** attempt)
    raise AppError(f"Gave up after {retries} tries: {url}")


# =============================================================== tokens ====
TOKEN_ENV = {"access_token": "TTS_ACCESS_TOKEN", "access_token_expire_in": "TTS_ACCESS_TOKEN_EXPIRES",
             "refresh_token": "TTS_REFRESH_TOKEN", "refresh_token_expire_in": "TTS_REFRESH_TOKEN_EXPIRES"}


def _save_tokens(d):
    """Store the login inside the .env so whoever has the .env is signed in."""
    if ENV_PATH:
        update_env(ENV_PATH, {v: d.get(k, "") for k, v in TOKEN_ENV.items()})
    else:
        TOKEN_FILE.write_text(json.dumps(d, indent=2))
    return d


def load_tokens():
    """Login from the .env; otherwise adopt an older tts_tokens.json (and copy it into the .env)."""
    if ENV_PATH and ENV_PATH.exists():
        v = env_vals(ENV_PATH)
        if v.get("TTS_REFRESH_TOKEN"):
            tok = {k: v.get(e, "") for k, e in TOKEN_ENV.items()}
            for k in ("access_token_expire_in", "refresh_token_expire_in"):
                tok[k] = int(tok[k]) if str(tok[k]).isdigit() else 0
            return tok
    places = [TOKEN_FILE, HERE.parent / "tts_tokens.json", Path.home() / "Downloads" / "tts_tokens.json",
              Path.home() / "OneDrive" / "Downloads" / "tts_tokens.json"]
    if ENV_PATH:
        places.insert(0, ENV_PATH.parent / "tts_tokens.json")
    for p in places:
        try:
            if p.exists():
                tok = json.loads(p.read_text())
                if tok.get("refresh_token"):
                    _save_tokens(tok)
                    return tok
        except (OSError, ValueError):
            pass
    return None


def _token_call(path, params):
    body = http_get_json(AUTH + path, params)
    if body.get("code") != 0:
        raise AppError(f"Token error {body.get('code')}: {body.get('message')}")
    return body["data"]


def get_access_token(key, secret, auth_code=None):
    if auth_code:
        d = _token_call("/api/v2/token/get", {"app_key": key, "app_secret": secret,
                                              "auth_code": auth_code.strip(), "grant_type": "authorized_code"})
        return _save_tokens(d)["access_token"]
    tok = load_tokens()
    if not tok:
        raise NeedAuthCode("This .env doesn't have a TikTok Shop login yet.")
    if tok.get("access_token_expire_in", 0) - time.time() < 3600:
        if tok.get("refresh_token_expire_in", 0) and tok["refresh_token_expire_in"] < time.time():
            raise NeedAuthCode("Saved login has expired.")
        try:
            tok = _save_tokens(_token_call("/api/v2/token/refresh", {
                "app_key": key, "app_secret": secret,
                "refresh_token": tok["refresh_token"], "grant_type": "refresh_token"}))
        except AppError as e:
            raise NeedAuthCode(f"Couldn't refresh login ({e}).")
    return tok["access_token"]


def extract_code(text):
    """Accept a bare code or a whole pasted URL containing code=..."""
    text = (text or "").strip()
    if "code=" in text:
        q = urllib.parse.urlparse(text).query or text.split("?", 1)[-1]
        return urllib.parse.parse_qs(q).get("code", [""])[0]
    return text


def browser_authorize(service_id, timeout=240):
    """Open TikTok's approval page and catch the code on http://localhost:8765/callback."""
    import http.server
    got = {}

    class H(http.server.BaseHTTPRequestHandler):
        def log_message(self, *a):
            pass

        def do_GET(self):
            qs = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            if "code" in qs:
                got["code"] = qs["code"][0]
            msg = ("<h2>Connected. You can close this tab and go back to the app.</h2>" if "code" in qs
                   else "<h2>No code received.</h2><p>Go back to the app and try again.</p>")
            self.send_response(200); self.send_header("Content-Type", "text/html; charset=utf-8"); self.end_headers()
            self.wfile.write(f"<html><body style='font-family:sans-serif;padding:40px'>{msg}</body></html>".encode())

    try:
        srv = http.server.HTTPServer(("127.0.0.1", CALLBACK_PORT), H)
    except OSError:
        raise AppError(f"Port {CALLBACK_PORT} is busy; close other copies of the app and retry.")
    srv.timeout = 1
    webbrowser.open(f"https://services.us.tiktokshop.com/open/authorize?service_id={service_id}")
    end = time.time() + timeout
    try:
        while "code" not in got and time.time() < end:
            srv.handle_request()
    finally:
        srv.server_close()
    return got.get("code")


# ============================================================== signing ====
def sign(path, params, secret, body=""):
    items = sorted((k, v) for k, v in params.items() if k not in ("sign", "access_token") and v is not None)
    s = secret + path + "".join(f"{k}{v}" for k, v in items) + (body or "") + secret
    return hmac.new(secret.encode(), s.encode(), hashlib.sha256).hexdigest()


class Client:
    def __init__(self, key, secret, token):
        self.key, self.secret, self.token, self.shop_cipher = key, secret, token, None

    def get(self, path, **params):
        params = {k: v for k, v in params.items() if v is not None}
        params.update(app_key=self.key)
        if self.shop_cipher:
            params.setdefault("shop_cipher", self.shop_cipher)
        for attempt in range(6):
            params["timestamp"] = int(time.time())
            params.pop("sign", None)
            params["sign"] = sign(path, params, self.secret)
            body = http_get_json(API + path, params, {"x-tts-access-token": self.token, "content-type": "application/json"})
            msg = str(body.get("message", "")).lower()
            if body.get("code") != 0 and ("limit" in msg or "too many" in msg or "frequen" in msg):
                time.sleep(min(30, 2 ** attempt))      # rate limited: back off and retry
                continue
            break
        if body.get("code") != 0:
            raise AppError(f"{path}: {body.get('code')} {body.get('message')}")
        return body.get("data") or {}


# ============================================================== export =====
def flatten(obj, prefix=""):
    out = {}
    for k, v in (obj or {}).items():
        key = f"{prefix}{k}"
        if isinstance(v, dict):
            out.update(flatten(v, key + "_"))
        elif isinstance(v, list):
            out[key] = json.dumps(v)
        else:
            out[key] = v
    return out


def write_csv(path, rows, lead):
    cols = list(lead)
    for r in rows:
        for k in r:
            if k not in cols:
                cols.append(k)
    with open(path, "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=cols, extrasaction="ignore")
        w.writeheader()
        w.writerows(rows)


def safe_write_csv(path, rows, lead, log):
    """Write the CSV; if it's locked (e.g. open in Excel), save under a new name instead."""
    try:
        write_csv(path, rows, lead)
        return path
    except PermissionError:
        alt = path.with_name(f"{path.stem}_{datetime.now():%H%M%S}{path.suffix}")
        write_csv(alt, rows, lead)
        log(f"  {path.name} is open in another program (Excel?), so saved as {alt.name}")
        return alt


def ts_local(v):
    try:
        return time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(int(v)))
    except (TypeError, ValueError):
        return v


def run_export(key, secret, start, end, log, auth_code=None, currency="USD"):
    """Returns (sessions_csv, minutes_csv)."""
    c = Client(key, secret, get_access_token(key, secret, auth_code))
    shops = c.get("/authorization/202309/shops").get("shops", [])
    if not shops:
        raise AppError("No shops are authorized for this login.")
    c.shop_cipher = shops[0]["cipher"]
    log(f"Shop: {shops[0].get('name')}   {start} → {end}")

    sessions = []
    for acct in ACCOUNT_TYPES:
        token = None
        while True:
            d = c.get("/analytics/202609/shop_lives/performance", start_date_ge=start.isoformat(),
                      end_date_lt=(end + timedelta(days=1)).isoformat(), account_type=acct,
                      page_size=100, currency=currency, page_token=token)
            for s in d.get("live_stream_sessions", []):
                s["_account_type"] = acct
                sessions.append(s)
            token = d.get("next_page_token")
            if not token:
                break
        log(f"  {acct}: data available through {d.get('latest_available_date')}")
    log(f"Found {len(sessions)} LIVE sessions. Pulling minute data ({WORKERS} at a time)…")

    cache_dir = EXPORTS / ".cache"; cache_dir.mkdir(parents=True, exist_ok=True)
    cutoff = (date.today() - timedelta(days=2)).isoformat()   # LIVEs older than this are final -> cacheable
    lock = threading.Lock(); done = [0]; hits = [0]

    def fetch(s):
        live_id = s.get("id")
        cf = cache_dir / f"{live_id}.json"
        if cf.exists():
            try:
                with lock: hits[0] += 1
                return json.loads(cf.read_text()), None, True
            except ValueError:
                pass
        intervals, overall, token = [], {}, None
        try:
            while True:
                d = c.get(f"/analytics/202510/shop_lives/{live_id}/performance_per_minutes",
                          currency=currency, page_token=token)
                perf = d.get("performance") or {}
                overall = overall or perf.get("overall") or {}
                intervals.extend(perf.get("intervals") or [])
                token = d.get("next_page_token")
                if not token:
                    break
        except AppError as e:
            return None, str(e), False
        data = {"overall": overall, "intervals": intervals}
        if intervals and str(s.get("start_time", ""))[:10] and str(s.get("start_time", ""))[:10] < cutoff:
            cf.write_text(json.dumps(data))
        return data, None, False

    def report(s, data, err, cached):
        user = (s.get("creator") or {}).get("user_name", "")
        with lock:
            done[0] += 1; n = done[0]
        if err:
            log(f"  [{n}/{len(sessions)}] {user}: skipped ({err[:90]}). Usually still live or not processed yet.")
        else:
            log(f"  [{n}/{len(sessions)}] {user:<20} {len(data['intervals'])} minutes{'  (cached)' if cached else ''}")

    from concurrent.futures import ThreadPoolExecutor, as_completed
    results = {}
    with ThreadPoolExecutor(max_workers=WORKERS) as ex:
        futs = {ex.submit(fetch, s): s for s in sessions}
        for f in as_completed(futs):
            s = futs[f]
            try:
                data, err, cached = f.result()
            except Exception as e:
                data, err, cached = None, str(e), False
            report(s, data, err, cached)
            results[s.get("id")] = data

    srows, mrows = [], []
    for s in sessions:                       # keep a stable order in the CSVs
        live_id, user = s.get("id"), (s.get("creator") or {}).get("user_name", "")
        row = flatten(s); row["account"] = user; srows.append(row)
        data = results.get(live_id)
        if not data:
            continue
        title = (data.get("overall") or {}).get("live_title") or s.get("title")
        for iv in data["intervals"]:
            r = {"account": user, "live_id": live_id, "live_title": title,
                 "minute_start": ts_local(iv.get("start_time")), "minute_end": ts_local(iv.get("end_time"))}
            r.update(flatten(iv)); mrows.append(r)
    if hits[0]:
        log(f"Reused {hits[0]} LIVE(s) from cache.")

    EXPORTS.mkdir(exist_ok=True)
    stamp = f"{start}_{end}"
    sp, mp = EXPORTS / f"live_sessions_{stamp}.csv", EXPORTS / f"live_minutes_{stamp}.csv"
    sp = safe_write_csv(sp, srows, ["account", "id", "title", "start_time", "end_time"], log)
    mp = safe_write_csv(mp, mrows, ["account", "live_id", "live_title", "minute_start", "minute_end"], log)
    log(f"Saved {len(srows)} sessions and {len(mrows):,} minute rows to the exports folder.")
    return sp, mp


# ============================================================ dashboard ====
DASHBOARD_B64 = ""


def build_dashboard(csv_paths, log):
    html = zlib.decompress(base64.b64decode(DASHBOARD_B64)).decode("utf-8")
    files, skipped = [], []
    for p in csv_paths:
        p = Path(p)
        text = p.read_text(encoding="utf-8-sig")
        header = text.split("\n", 1)[0]
        if "live_id" in header and ("minute_start" in header or "start_time" in header):
            files.append({"name": p.name, "text": text})
        else:
            skipped.append(p.name)
    if skipped:
        log("Not minute files (skipped): " + ", ".join(skipped))
    if not files:
        raise AppError("None of the chosen files are live_minutes CSVs.")
    payload = json.dumps(files).replace("</", "<\\/")
    html = html.replace("<!--__EMBED_DATA__-->",
                        f'<script id="embedded-data" type="application/json">{payload}</script>', 1)
    DASHBOARDS.mkdir(exist_ok=True)
    out = DASHBOARDS / f"LIVE_dashboard_{datetime.now():%Y-%m-%d_%H%M}.html"
    out.write_text(html, encoding="utf-8")
    log(f"Dashboard saved: {out}")
    return out


# ================================================================== GUI ====
def run_gui():
    import tkinter as tk
    from tkinter import ttk, messagebox, filedialog, simpledialog, scrolledtext

    root = tk.Tk()
    root.title(APP_NAME)
    root.geometry("720x520")
    root.minsize(560, 420)
    q = queue.Queue()
    state = {"env": find_env(), "busy": False}

    frm = ttk.Frame(root, padding=16); frm.pack(fill="both", expand=True)
    ttk.Label(frm, text=APP_NAME, font=("Segoe UI", 16, "bold")).pack(anchor="w")
    ttk.Label(frm, text="Export TikTok Shop LIVE data and build the dead-zone dashboard.",
              foreground="#555").pack(anchor="w", pady=(0, 10))
    envvar, tokvar = tk.StringVar(), tk.StringVar()
    ttk.Label(frm, textvariable=envvar).pack(anchor="w")
    ttk.Label(frm, textvariable=tokvar).pack(anchor="w", pady=(0, 10))

    bar = ttk.Frame(frm); bar.pack(fill="x", pady=(0, 10))
    start_btn = ttk.Button(bar, text="▶  Start", command=lambda: step_ask_export())
    start_btn.pack(side="left", ipadx=14, ipady=6)
    ttk.Button(bar, text="Choose .env…", command=lambda: pick_env()).pack(side="left", padx=8)
    ttk.Button(bar, text="Open folder", command=lambda: open_path(HERE)).pack(side="left")
    prog = ttk.Progressbar(frm, mode="indeterminate"); prog.pack(fill="x", pady=(0, 8))
    logbox = scrolledtext.ScrolledText(frm, height=16, font=("Consolas", 9), state="disabled")
    logbox.pack(fill="both", expand=True)

    def log(msg):  # thread-safe
        q.put(("log", msg))

    def pump():
        try:
            while True:
                kind, val = q.get_nowait()
                if kind == "log":
                    logbox.configure(state="normal"); logbox.insert("end", val + "\n"); logbox.see("end"); logbox.configure(state="disabled")
                elif kind == "call":
                    val()
        except queue.Empty:
            pass
        root.after(100, pump)

    def refresh_status():
        envvar.set(f"✔ .env: {state['env']}" if state["env"] else "✖ No settings file found next to this app (.env or env.txt). Click 'Choose .env…'")
        has = False
        if state["env"]:
            try:
                load_env(state["env"]); has = load_tokens() is not None
            except Exception:
                pass
        tokvar.set("✔ TikTok Shop login found in .env (no sign-in needed)" if has
                   else "• No TikTok Shop login in this .env yet. The first export will connect it once")

    def open_path(p):
        try:
            if sys.platform == "win32":
                os.startfile(p)
            elif sys.platform == "darwin":
                import subprocess; subprocess.run(["open", str(p)])
            else:
                webbrowser.open(Path(p).as_uri())
        except Exception:
            webbrowser.open(Path(p).as_uri())

    def pick_env():
        p = filedialog.askopenfilename(title="Choose your .env file", initialdir=str(HERE),
                                       filetypes=[("Settings files", "*.env .env *.txt"), ("All files", "*.*")])
        if p:
            state["env"] = Path(p); refresh_status()

    def busy(on):
        state["busy"] = on
        start_btn.configure(state="disabled" if on else "normal")
        prog.start(12) if on else prog.stop()

    # ---- step 1: export? ----
    def step_ask_export():
        if state["busy"]:
            return
        if not state["env"]:
            pick_env()
            if not state["env"]:
                return
        try:
            key, secret = load_env(state["env"])
        except AppError as e:
            messagebox.showerror(APP_NAME, str(e)); return
        if messagebox.askyesno(APP_NAME, "Export fresh LIVE data from TikTok Shop first?\n\n"
                                         "Yes = pull new CSVs, then choose files\nNo = go straight to choosing CSVs"):
            days = simpledialog.askinteger(APP_NAME, "How many days back should I export?\n(TikTok data usually lags 1–2 days)",
                                           initialvalue=7, minvalue=1, maxvalue=90, parent=root)
            if not days:
                return
            end = date.today(); start = end - timedelta(days=days)
            start_export(key, secret, start, end, None)
        else:
            step_choose_csvs(None)

    def start_export(key, secret, start, end, auth_code):
        busy(True); log(f"\n=== Export {start} → {end} ===")

        def work():
            try:
                _, mp = run_export(key, secret, start, end, log, auth_code)
                q.put(("call", lambda mp=mp: (busy(False), refresh_status(), step_choose_csvs(mp))))
            except NeedAuthCode as e:
                q.put(("call", lambda e=e: (busy(False), ask_auth_code(key, secret, start, end, str(e)))))
            except Exception as e:
                log("ERROR: " + str(e)); log(traceback.format_exc(limit=2))
                q.put(("call", lambda e=e: (busy(False), messagebox.showerror(APP_NAME, f"Export failed:\n{e}"))))
        threading.Thread(target=work, daemon=True).start()

    def ask_auth_code(key, secret, start, end, why):
        if messagebox.askyesno(APP_NAME, f"{why}\n\nConnect it now? Your browser will open TikTok Shop. "
                               "Sign in to the shop and click Authorize. The app picks up the rest.\n\n"
                               "This only happens once. The login is then saved in the .env, so anyone "
                               "using this .env is signed in automatically.\n\n"
                               "(Choose No to paste a code manually instead.)"):
            busy(True); log("Waiting for approval in your browser (up to 4 minutes)…")
            sid = env_vals(state["env"]).get("TTS_SERVICE_ID") or SERVICE_ID

            def work():
                try:
                    code = browser_authorize(sid)
                except Exception as e:
                    code = None; log("Browser sign-in failed: " + str(e))
                if code:
                    log("Approved. Saving login to .env…")
                    q.put(("call", lambda code=code: (busy(False), start_export(key, secret, start, end, code))))
                else:
                    log("No approval came back to the app. If the browser landed on another page showing a code, paste it.")
                    q.put(("call", lambda: (busy(False), paste_code(key, secret, start, end))))
            threading.Thread(target=work, daemon=True).start()
        else:
            paste_code(key, secret, start, end)

    def paste_code(key, secret, start, end):
        code = simpledialog.askstring(APP_NAME,
            "Paste the auth code, or the whole address of the page you landed on after approving:\n\n"
            "(Partner Center → App & Service → KPI Dashboard → Authorization → 'Seller' → "
            "Copy authorization link → open it → approve.)", parent=root)
        code = extract_code(code)
        if code:
            start_export(key, secret, start, end, code)

    # ---- step 2: choose CSVs ----
    def step_choose_csvs(just_made):
        EXPORTS.mkdir(exist_ok=True)
        hint = f"\n\nJust exported: {Path(just_made).name}" if just_made else ""
        messagebox.showinfo(APP_NAME, "Choose the live_minutes CSV file(s) to put in the dashboard.\n"
                                      "Hold Ctrl to pick several date ranges." + hint)
        paths = filedialog.askopenfilenames(title="Choose live_minutes CSV files", initialdir=str(EXPORTS),
                                            filetypes=[("LIVE minute CSVs", "live_minutes_*.csv"), ("CSV files", "*.csv"), ("All files", "*.*")])
        if not paths:
            log("No files chosen."); return
        step_build(paths)

    # ---- step 3: build + open ----
    def step_build(paths):
        busy(True); log(f"\n=== Building dashboard from {len(paths)} file(s) ===")

        def work():
            try:
                out = build_dashboard(paths, log)
                q.put(("call", lambda out=out: (busy(False), webbrowser.open(out.as_uri()), log("Opened in your browser. ✔"))))
            except Exception as e:
                log("ERROR: " + str(e))
                q.put(("call", lambda e=e: (busy(False), messagebox.showerror(APP_NAME, str(e)))))
        threading.Thread(target=work, daemon=True).start()

    refresh_status()
    log(f"Ready. Folder: {HERE}\nPress Start.")
    pump()
    root.mainloop()


if __name__ == "__main__":
    try:
        run_gui()
    except Exception:
        # Last-resort error display (e.g. when run as .pyw with no console)
        err = traceback.format_exc()
        try:
            import tkinter as tk
            from tkinter import messagebox
            r = tk.Tk(); r.withdraw(); messagebox.showerror(APP_NAME, err)
        except Exception:
            print(err)
